mapper.select:
SELECT CASE WHEN COUNT(1) > 0 THEN 1 ELSE 0 END
FROM permissions
WHERE permission_url = #{urlPattern}
AND permission_method = #{method}


SELECT CASE WHEN COUNT(*) > 0 THEN 1 ELSE 0 END
FROM projects p
         LEFT JOIN project_members pm ON p.project_id = pm.project_id AND pm.user_id = #{userId}
WHERE p.project_id = #{projectId}
  AND (
    p.is_public = 'P1'           -- 조건 1: 전체 공개 프로젝트이거나
        OR pm.user_id IS NOT NULL    -- 조건 2: 멤버 테이블에 내 ID가 존재하거나
    )

SELECT CASE WHEN COUNT(1) > 0 THEN 1 ELSE 0 END
FROM GROUP_PERMISSIONS gp
JOIN permissions p ON gp.permission_id = p.permission_id
WHERE gp.group_id = #{groupId}
AND p.permission_url = #{targetUrl}
AND p.permission_method = #{method}
